import { useEffect, useState } from 'react'
import type { TrackDefinition } from './types'

// Track files are generated by tools/TrackBuilder and named by Natsoft track code (e.g. MOUN.json).
// They're loaded on demand so adding circuits doesn't grow the main bundle.
const loaders = import.meta.glob<{ default: TrackDefinition }>(['./*.json', '!./manifest.json'])
// Small index written by TrackBuilder: track code -> Natsoft track-name fragments. Bundled up front so a
// track can be found by name when its code is unknown.
import manifest from './manifest.json'
export interface ManifestEntry { name: string; match: string[]; provisional: boolean }
export const trackManifest = manifest as Record<string, ManifestEntry>
const matches: Record<string, string[] | undefined> = Object.fromEntries(
  Object.entries(trackManifest).map(([code, entry]) => [`./${code}.json`, entry.match]),
)

/** File for a Natsoft track: by code first, then by a `match` fragment found in the track name. */
function findFile(code: string | undefined, name: string | undefined): string | undefined {
  if (code && `./${code}.json` in loaders) return `./${code}.json`
  const upper = (name ?? '').toUpperCase()
  if (!upper) return undefined
  return Object.entries(matches).find(([, m]) => m?.some((frag) => upper.includes(frag.toUpperCase())))?.[0]
}

/** Loads the track for the session. Returns null while loading or if there's no file. */
export function useTrack(code: string | undefined, name?: string): TrackDefinition | null {
  const [track, setTrack] = useState<TrackDefinition | null>(null)
  const file = findFile(code, name)
  useEffect(() => {
    setTrack(null)
    const load = file ? loaders[file] : undefined
    if (!load) return
    let cancelled = false
    load().then((m) => !cancelled && setTrack(m.default))
    return () => {
      cancelled = true
    }
  }, [file])
  return track
}
